`timescale 1ns/1ps
module tb_tessera_execution_system;
localparam N=4,OW=3,TW=8,DW=16,AW=32,CW=2,D=4; logic clk=0,rst_n=0,completion_valid,completion_ready=1; logic [N-1:0] req=0,grant,unit_select_bus=0; logic [N*OW-1:0] op_bus=0; logic [N*TW-1:0] tag_bus=0; logic [N*DW-1:0] operand_a_bus=0,operand_b_bus=0; logic [N*AW-1:0] accumulator_bus=0; logic [CW-1:0] completion_client; logic [TW-1:0] completion_tag; logic [1:0] completion_status; logic [AW-1:0] completion_result; logic [$clog2(D+1)-1:0] completion_occupancy; integer timeout; always #5 clk=~clk; tessera_execution_system dut(.*); task tick; begin @(posedge clk); #1; end endtask
initial begin repeat(2) tick(); rst_n=1; tick(); op_bus[0+:OW]=0; tag_bus[0+:TW]=8'h11; operand_a_bus[0+:DW]=10; operand_b_bus[0+:DW]=20; @(negedge clk); req=1; #1; if(grant!==1) $fatal(1,"vector grant"); tick(); req=0; timeout=0; while(!completion_valid&&timeout<20) begin tick(); timeout=timeout+1; end if(!completion_valid||completion_client!==0||completion_tag!==8'h11||completion_result!==30||completion_status!==0) $fatal(1,"vector result"); tick();
unit_select_bus[1]=1; op_bus[OW+:OW]=1; tag_bus[TW+:TW]=8'h22; operand_a_bus[DW+:DW]=3; operand_b_bus[DW+:DW]=4; accumulator_bus[AW+:AW]=5; @(negedge clk); req=2; #1; if(grant!==2) $fatal(1,"tensor grant"); tick(); req=0; timeout=0; while(!completion_valid&&timeout<20) begin tick(); timeout=timeout+1; end if(!completion_valid||completion_client!==1||completion_tag!==8'h22||completion_result!==17||completion_status!==0) $fatal(1,"tensor result"); tick(); $display("PASS shared vector/tensor routing and common completion FIFO"); $finish; end
endmodule
